    fn mclass(&mut self) -> R<Next> {
        let xt = self.upop()?;
        self.cpu.r[EBX as usize] = xt;
        Ok(Next::Jump(xt))
    }

    fn not_implemented(g: Gate) -> Fault {
        Fault::NotImplemented(match g {
            Gate::MakeExe => "makeexe",
            Gate::Syscall => "syscall",
            Gate::LzPack => ">lz",
            Gate::LzDepack => "lz>",
            Gate::LzMax => "lzmax",
            Gate::LoadLib => "(lib)",
            Gate::UnloadLib => "(-lib)",
            Gate::CallFn => "(call)",
            Gate::OsFunc => "(func)",
            _ => g.name(),
        })
    }

    // ---- the dispatcher ------------------------------------------------

    fn gate(&mut self, g: Gate, host: &mut dyn Host) -> R<Next> {
        use Gate::*;
        use Next::{Call, Jump, Ret};
        match g {
            // --- classes: called with EAX = xt, EDX = dictionary entry ---
            FClass | FClassNotail => {
                self.setv(st::SSEMI_DO_TAIL, if g == FClass { 0x90 } else { 0xc3 })?;
                if self.compiling() {
                    let xt = self.upop()?;
                    self.compile_call(xt)?;
                    Ok(Ret)
                } else {
                    self.mclass()
                }
            }
            MClass => self.mclass(),
            MClassNotail => {
                self.setv(st::SSEMI_DO_TAIL, 0xc3)?;
                self.mclass()
            }
            IClass => {
                self.setv(st::SSEMI_DO_TAIL, 0xc3)?;
                if !self.compiling() {
                    return self.mclass();
                }
                let xt = self.upop()?;
                let n = self.mem.read_u8(xt.wrapping_sub(1))? as u32;
                self.cpu.r[EDX as usize] = xt;
                self.store_here(xt, n)?;
                Ok(Ret)
            }
            CClass => {
                // `cclass` has no `ret`: it falls through into `vclass`, so
                // while compiling the constant's value becomes a literal.
                let v = self.mem.read_u32(self.eax())?;
                self.set_eax(v);
                if self.compiling() {
                    let v = self.upop()?;
                    self.compile_literal(v)?;
                }
                Ok(Ret)
            }
            VClass => {
                if self.compiling() {
                    let v = self.upop()?;
                    self.compile_literal(v)?;
                }
                Ok(Ret)
            }
            ValClass => {
                if self.compiling() {
                    let v = self.upop()?;
                    self.compile_literal(v)?;
                    self.compile_call(CClass.addr())?;
                } else {
                    let v = self.mem.read_u32(self.eax())?;
                    self.set_eax(v);
                }
                Ok(Ret)
            }
            DoesClass => {
                // xt-4 holds the address of the code after `does>`.
                self.dup()?;
                let code = self.mem.read_u32(self.eax().wrapping_sub(4))?;
                self.set_eax(code);
                if !self.compiling() {
                    return self.mclass();
                }
                let code = self.upop()?;
                let xt = self.upop()?;
                self.compile_literal(xt)?;
                self.compile_call(code)?;
                Ok(Ret)
            }
            DClass => {
                if self.compiling() {
                    // call dword [xt]
                    let xt = self.upop()?;
                    let mut b = [0xff, 0x15, 0, 0, 0, 0];
                    b[2..].copy_from_slice(&xt.to_le_bytes());
                    self.emit_code(&b)?;
                    Ok(Ret)
                } else {
                    let cell = self.upop()?;
                    self.cpu.r[EBX as usize] = cell;
                    Ok(Jump(self.mem.read_u32(cell)?))
                }
            }

            // --- default DEFER targets ---
            Noop => Ok(Ret),
            OsEmit => {
                let c = self.upop()?;
                host.write(&[c as u8]);
                Ok(Ret)
            }
            OsType => {
                // The original passed `n` to write(2); a negative count (as
                // `srcstr` yields at the keyboard: `src` is 0 there) made the
                // kernel refuse with EFAULT and print nothing.  Same here.
                let n = self.upop()?;
                let a = self.upop()?;
                if n != 0 && (n as i32) > 0 {
                    host.write(self.mem.slice(a, n)?);
                }
                Ok(Ret)
            }
            OsKey => match self.input.pop_front() {
                Some(b) => {
                    self.upsh(b as u32)?;
                    Ok(Ret)
                }
                None if self.input_closed => {
                    self.upsh(EOF_KEY)?;
                    Ok(Ret)
                }
                None => Ok(Next::NeedInput),
            },
            OsBye => Ok(Next::Halt(self.eax() as i32)),
            Find => {
                // ( a n -- entry | a n 0 )
                let n = self.upop()?;
                let a = self.eax();
                let name = self.mem.slice(a, n)?.to_vec();
                match self.find_entry(&name) {
                    Some(e) => self.set_eax(e),
                    None => {
                        self.upsh(n)?;
                        self.upsh(0)?;
                    }
                }
                Ok(Ret)
            }
            WordNotFound => {
                // ( a n -- 0 ): print "name?" and give up on the token.
                self.call_type(host)?;
                self.call_emit(host, b'?')?;
                self.call_emit(host, b'\n')?;
                self.upsh(0)?;
                Ok(Ret)
            }
            HeaderDefault => {
                self.header_default(host)?;
                Ok(Ret)
            }
            Hello => {
                // `_hello`: include argv[1] if given, then run the REPL.
                if self.var(st::ARGC) > 1 {
                    let p = self.mem.read_u32(self.var(st::ARGV) + 4)?;
                    let n = self.zlen(p)?;
                    self.upsh(p)?;
                    self.upsh(n)?;
                    Ok(Call(Include2.addr(), Repl))
                } else {
                    Ok(Jump(Repl.addr()))
                }
            }

            // --- startup ---
            Cold => {
                self.cpu.r[SI] = S0;
                self.set_eax(0);
                self.setv(st::RP0_SAVED, self.cpu.r[ESP as usize])?;
                self.iterate_list(host, OnStartThunk.addr(), st::START_LIST)?;
                Ok(Call(self.var(st::APPSTART), ColdDone))
            }
            BootRestart => {
                // reva.f's last step saved a native executable; running that
                // executable started with fresh stacks and no source file,
                // ran the `onstartup` list (which allocates `scratch`, `pad`
                // ...) and then `appstart`.  Do the same in place: drop the
                // boot file from argv, abandon the include frames, restart.
                // TOS is reva.f's interpreter loop, for fault recovery.
                let repl = self.upop()?;
                self.setv(st::REPL_ENTRY, repl)?;
                self.setv(st::ARGC, 1)?;
                self.setv(st::SOURCE, 0)?;
                self.setv(st::TP, TIB)?;
                self.setv(st::TIN, TIB)?;
                self.setv(st::IS_COMPILING, 0)?;
                self.cpu.r[ESP as usize] = RP0;
                Ok(Jump(Cold.addr()))
            }
            ColdDone => {
                self.set_eax(u32::MAX);
                Ok(Jump(Bye.addr()))
            }
            Repl => Ok(Call(Interpret.addr(), Repl)),
            OnStartThunk => Ok(Jump(self.mem.read_u32(self.eax())?)),

            // --- interpret / query ---
            Interpret => {
                let src = self.var(st::SOURCE);
                if src != 0 {
                    if self.var(st::TIN) >= src {
                        return Ok(Ret);
                    }
                    self.setv(st::TP, src)?;
                    return Ok(Jump(InterpWord.addr()));
                }
                self.call_vector(host, st::PROMPT)?;
                self.setv(st::TP, TIB)?;
                self.setv(st::TIN, TIB)?;
                Ok(Jump(QueryKey.addr()))
            }
            QueryKey => {
                let key = self.var(st::KEY);
                if key != OsKey.addr() {
                    return Ok(Call(key, QueryKeyGot));
                }
                loop {
                    let c = match self.input.pop_front() {
                        Some(b) => b as u32,
                        None if self.input_closed => EOF_KEY,
                        None => return Ok(Next::NeedInput),
                    };
                    if let Some(next) = self.query_char(c)? {
                        return Ok(next);
                    }
                }
            }
            QueryKeyGot => {
                let c = self.upop()?;
                Ok(self.query_char(c)?.unwrap_or(Jump(QueryKey.addr())))
            }
            InterpWord => {
                if self.cpu.r[SI] > S0 {
                    return Err(Fault::StackUnderflow);
                }
                let (a, n) = self.parsews(host)?;
                if n == 0 {
                    return Ok(Jump(Interpret.addr()));
                }
                self.upsh(a)?;
                self.upsh(n)?;
                Ok(Call(self.var(st::FINDINTERNAL), InterpFound))
            }
            InterpFound => {
                if self.eax() != 0 {
                    return self.after_ok(1);
                }
                self.drop1()?;
                let (a, n) = (self.nos()?, self.eax());
                if let Some(v) = self.parse_single(a, n)? {
                    self.drop1()?;
                    self.set_eax(v);
                    return self.after_ok(2);
                }
                if let Some((lo, hi)) = self.parse_double(a, n)? {
                    self.set_nos(lo)?;
                    self.set_eax(hi);
                    return self.after_ok(3);
                }
                Ok(Call(self.var(st::IS_WORD), InterpIsWord))
            }
            InterpIsWord => {
                let kind = self.upop()?;
                if kind != 0 {
                    return self.after_ok(kind);
                }
                // `.fail`: abandon a half-made definition, leave interpret.
                self.rollback_definition()?;
                Ok(Ret)
            }
            Eval => {
                let n = self.upop()?;
                let a = self.upop()?;
                self.rpush(self.var(st::SOURCE))?;
                self.rpush(self.var(st::TIN))?;
                self.rpush(self.var(st::TP))?;
                self.setv(st::SOURCE, a.wrapping_add(n))?;
                self.setv(st::TIN, a)?;
                Ok(Call(Interpret.addr(), EvalDone))
            }
            EvalDone => {
                let tp = self.rpop()?;
                let tin = self.rpop()?;
                let src = self.rpop()?;
                self.setv(st::TP, tp)?;
                self.setv(st::TIN, tin)?;
                self.setv(st::SOURCE, src)?;
                Ok(Ret)
            }
            Include => {
                let (a, n) = self.parsews(host)?;
                self.upsh(a)?;
                self.upsh(n)?;
                Ok(Jump(Include2.addr()))
            }
            Include2 => {
                // `__include` ( a n -- ): slurp, eval, free.  As in the
                // original, the data stack is restored afterwards.
                if !self.slurp(host)? {
                    self.drop1()?;
                    self.drop1()?;
                    self.setv(st::IOR, 1)?;
                    return Ok(Ret);
                }
                self.rpush(self.nos()?)?;
                self.rpush(self.cpu.r[SI])?;
                self.rpush(self.eax())?;
                Ok(Call(Eval.addr(), IncludeDone))
            }
            IncludeDone => {
                let eax = self.rpop()?;
                self.cpu.r[SI] = self.rpop()?;
                self.set_eax(eax);
                self.drop1()?;
                let ptr = self.rpop()?;
                self.heap.free(ptr);
                self.drop1()?;
                self.setv(st::IOR, 0)?;
                Ok(Ret)
            }

            // --- catch / throw: ESP-based frames, exactly as in newcore ---
            Catch => {
                self.rpush(self.cpu.r[SI])?;
                self.rpush(self.var(st::HANDLER))?;
                self.setv(st::HANDLER, self.cpu.r[ESP as usize])?;
                let xt = self.upop()?;
                self.cpu.r[EBX as usize] = xt;
                Ok(Call(xt, CatchDone))
            }
            CatchDone => {
                let h = self.rpop()?;
                self.setv(st::HANDLER, h)?;
                self.rpop()?;
                self.upsh(0)?;
                Ok(Ret)
            }
            Throw => {
                let h = self.var(st::HANDLER);
                if self.eax() == 0 || h == 0 {
                    self.drop1()?;
                    return Ok(Ret);
                }
                self.cpu.r[ESP as usize] = h;
                let prev = self.rpop()?;
                self.setv(st::HANDLER, prev)?;
                self.cpu.r[SI] = self.rpop()?;
                Ok(Ret)
            }
            NestedReturn => {
                if self.nested == 0 {
                    return Err(Fault::BadGate { addr: g.addr() });
                }
                Ok(Next::NestedReturn)
            }

            // --- defining words ---
            Header => {
                let (a, n) = self.parsews(host)?;
                self.upsh(a)?;
                self.upsh(n)?;
                Ok(Jump(self.var(st::HEADER_)))
            }
            Colon => {
                let (a, n) = self.parsews(host)?;
                self.upsh(a)?;
                self.upsh(n)?;
                Ok(Call(self.var(st::HEADER_), RBracket))
            }
            Tick => {
                let (a, n) = self.parsews(host)?;
                self.upsh(a)?;
                self.upsh(n)?;
                Ok(Call(self.var(st::FINDINTERNAL), TickDone))
            }
            TickDone => {
                if self.eax() == 0 {
                    self.drop1()?;
                    self.drop1()?;
                    self.set_eax(0);
                } else {
                    let xt = self.mem.read_u32(self.eax() + 4)?;
                    self.set_eax(xt);
                }
                Ok(Ret)
            }
            Variable => {
                self.upsh(0)?;
                Ok(Jump(Variable2.addr()))
            }
            Variable2 => {
                self.rpush(self.var(st::DEFAULT_CLASS))?;
                self.setv(st::DEFAULT_CLASS, VClass.addr())?;
                let (a, n) = self.parsews(host)?;
                self.upsh(a)?;
                self.upsh(n)?;
                Ok(Call(self.var(st::HEADER_), Variable2Done))
            }
            Variable2Done => {
                let dc = self.rpop()?;
                self.setv(st::DEFAULT_CLASS, dc)?;
                self.comma_n(4)?;
                Ok(Ret)
            }
            Literal => {
                let v = self.upop()?;
                self.compile_literal(v)?;
                Ok(Ret)
            }
            SSemi => {
                self.ssemi()?;
                Ok(Ret)
            }
            Semi => {
                self.ssemi()?;
                self.lbracket()?;
                Ok(Ret)
            }
            InlineSemi => {
                self.inline_semi()?;
                Ok(Ret)
            }
            LBracket => {
                self.lbracket()?;
                Ok(Ret)
            }
            RBracket => {
                let s = self.var(st::IS_COMPILING);
                self.setv(st::IS_COMPILING, s.wrapping_add(1))?;
                Ok(Ret)
            }
            Compile => {
                let xt = self.upop()?;
                self.compile_call(xt)?;
                Ok(Ret)
            }
            Align => {
                self.align_code()?;
                Ok(Ret)
            }
            StoreHere => {
                let n = self.upop()?;
                let a = self.upop()?;
                self.store_here(a, n)?;
                Ok(Ret)
            }
            Comma | Comma3 | Comma2 | Comma1 => {
                let n = match g {
                    Comma => 4,
                    Comma3 => 3,
                    Comma2 => 2,
                    _ => 1,
                };
                self.comma_n(n)?;
                Ok(Ret)
            }

            // --- parsing and numbers ---
            Parsews => {
                let (a, n) = self.parsews(host)?;
                self.upsh(a)?;
                self.upsh(n)?;
                Ok(Ret)
            }
            Parse => {
                self.parse()?;
                Ok(Ret)
            }
            ParseEsc => {
                self.parse_escaped()?;
                Ok(Ret)
            }
            Single => {
                let (a, n) = (self.nos()?, self.eax());
                match self.parse_single(a, n)? {
                    Some(v) => {
                        self.drop1()?;
                        self.set_eax(v);
                        self.upsh(u32::MAX)?;
                    }
                    None => self.upsh(0)?,
                }
                Ok(Ret)
            }
            Double => {
                let (a, n) = (self.nos()?, self.eax());
                match self.parse_double(a, n)? {
                    Some((lo, hi)) => {
                        self.set_nos(lo)?;
                        self.set_eax(hi);
                        self.upsh(u32::MAX)?;
                    }
                    None => self.upsh(0)?,
                }
                Ok(Ret)
            }
            FromDigit => {
                let v = digit_value(self.eax(), self.var(st::BASE)).unwrap_or(u32::MAX);
                self.set_eax(v);
                Ok(Ret)
            }
            ToDigit => {
                let n = self.eax();
                let c = if n < 16 {
                    DIGITS[n as usize] as u32
                } else {
                    let base = self.var(st::BASE);
                    if base == 0 {
                        return Err(Fault::DivideError { eip: g.addr() });
                    }
                    let c = n % base + 0x30;
                    if c > 0x39 { c + 39 } else { c }
                };
                self.set_eax(c);
                Ok(Ret)
            }
            PrintR => {
                self.print_r()?;
                Ok(Ret)
            }

            // --- memory and strings ---
            TwoDup => {
                let a = self.nos()?;
                let b = self.eax();
                let sp = self.cpu.r[SI].wrapping_sub(8);
                self.mem.write_u32(sp, a)?;
                self.mem.write_u32(sp + 4, b)?;
                self.cpu.r[SI] = sp;
                Ok(Ret)
            }
            Move => {
                let n = self.upop()?;
                let dst = self.upop()?;
                let src = self.upop()?;
                self.mem.move_forward(src, dst, n)?;
                Ok(Ret)
            }
            Fill => {
                let c = self.upop()?;
                let n = self.upop()?;
                let a = self.upop()?;
                self.mem.fill(a, n, c as u8)?;
                Ok(Ret)
            }
            Place | PlusPlace => {
                let buf = self.upop()?;
                let len = self.upop()?;
                let s = self.upop()?;
                if buf == 0 {
                    return Ok(Ret);
                }
                let dest = if g == Place {
                    if s == 0 {
                        self.mem.write_u8(buf, 0)?;
                        return Ok(Ret);
                    }
                    self.mem.write_u8(buf, len as u8)?;
                    buf + 1
                } else {
                    let cnt = self.mem.read_u8(buf)?;
                    self.mem.write_u8(buf, cnt.wrapping_add(len as u8))?;
                    buf + cnt as u32 + 1
                };
                self.mem.move_forward(s, dest, len)?;
                self.mem.write_u8(dest + len, 0)?;
                Ok(Ret)
            }
            Zt => {
                let len = self.upop()?;
                let s = self.eax();
                if s != 0 {
                    self.mem.write_u8(s.wrapping_add(len), 0)?;
                }
                Ok(Ret)
            }
            Zcount => {
                let s = self.eax();
                let n = if s == 0 { 0 } else { self.zlen(s)? };
                self.upsh(n)?;
                Ok(Ret)
            }
            Cmp | Cmpi => {
                self.compare(g == Cmpi)?;
                Ok(Ret)
            }
            FnvHash => {
                let n = self.upop()?;
                let a = self.eax();
                let mut h: u32 = 2_166_136_261;
                for &b in self.mem.slice(a, n)? {
                    h = (h ^ b as u32).wrapping_mul(16_777_619);
                }
                self.set_eax(h);
                Ok(Ret)
            }
            Allocate => {
                let a = self.heap.alloc(self.eax()).unwrap_or(0);
                self.set_eax(a);
                self.setv(st::IOR, (a == 0) as u32)?;
                Ok(Ret)
            }
            Free => {
                let a = self.upop()?;
                self.heap.free(a);
                self.setv(st::IOR, 0)?;
                Ok(Ret)
            }
            Resize => {
                self.resize()?;
                Ok(Ret)
            }
            Slurp => {
                self.slurp(host)?;
                Ok(Ret)
            }
            SetExtra => {
                let n = self.upop()?;
                let a = self.upop()?;
                self.setv(st::EXTRA_SIZE, n)?;
                self.setv(st::EXTRA_DATA, a)?;
                Ok(Ret)
            }
            GetExtra => {
                self.upsh(self.var(st::EXTRA_DATA))?;
                self.upsh(self.var(st::EXTRA_SIZE))?;
                Ok(Ret)
            }

            // --- lists and handlers ---
            Link => {
                self.link()?;
                Ok(Ret)
            }
            Link2 => {
                self.link_end()?;
                Ok(Ret)
            }
            OnExit => {
                self.upsh(st::EXIT_LIST)?;
                self.link()?;
                Ok(Ret)
            }
            OnStartup => {
                self.upsh(st::START_LIST)?;
                self.link_end()?;
                Ok(Ret)
            }
            Iterate => {
                let list = self.upop()?;
                let xt = self.upop()?;
                self.iterate_list(host, xt, list)?;
                Ok(Ret)
            }
            Reset => {
                self.cpu.r[SI] = S0;
                self.set_eax(0);
                self.setv(st::RP0_SAVED, self.cpu.r[ESP as usize])?;
                Ok(Ret)
            }
            Bye => {
                // run `onexit` handlers, then exit with TOS as the status
                let code = self.eax();
                self.iterate_list(host, OnStartThunk.addr(), st::EXIT_LIST)?;
                Ok(Next::Halt(code as i32))
            }
            Restart => {
                // like `bye` (onexit handlers run), but the host starts over
                self.iterate_list(host, OnStartThunk.addr(), st::EXIT_LIST)?;
                Ok(Next::Restart)
            }
            Version => {
                host.write(crate::version::info().as_bytes());
                Ok(Ret)
            }

            // --- OS services not yet provided by the portable core ---
            // --- portable OS layer (ffi.rs) ---
            LoadLib => self.ffi_loadlib().map(|()| Ret),
            UnloadLib => self.ffi_unloadlib().map(|()| Ret),
            OsFunc => self.ffi_func(host).map(|()| Ret),
            CallFn => self.ffi_call(host),
            Syscall => self.ffi_syscall(host).map(|()| Ret),
            HostGetenv | HostPutenv | HostLocaltime | HostOpendir | HostReaddir | HostClosedir
            | HostSystem | TtForward | TtStep | TtRight | TtPen | TtColor | TtWidth | TtHome
            | TtClear | TtClean | TtSetxy | TtSetheading | TtSetstep | TtScale | TtShow | TtX
            | TtY | TtHeading | TtPush | TtPop | TtPath | TtSvg | TtBg | TtSegments | HlType
            | HlColor | SqRc | SqVersion | SqOpen | SqClose | SqExec | SqLastid | SqErrmsg
            | SqQuery | SqNext | SqGetcol | SqEndquery | SqPrepare | SqBindNull | SqBindInt
            | SqBindText | SqBindBlob | SqBindZeroblob | SqReset | SqClear | SqStep
            | SqFinalize | SqColumnInt | SqColumnText | SqColumnBlob | SqPtr | IcOpen | Iconv
            | IcClose => Err(Fault::NotImplemented("a C function called without (call)")),

            // --- files (fileio.rs) ---
            OpenR => self.word_open(host, Access::Read).map(|()| Ret),
            OpenRw => self.word_open(host, Access::ReadWrite).map(|()| Ret),
            Creat => self.word_open(host, Access::Create).map(|()| Ret),
            Close => self.word_close(host).map(|()| Ret),
            Read => self.word_read(host).map(|()| Ret),
            Write => self.word_write(host).map(|()| Ret),
            Fsize => self.word_fsize(host).map(|()| Ret),
            Save => self.word_save(host).map(|()| Ret),

            MakeExe | LzPack | LzDepack | LzMax => Err(Self::not_implemented(g)),
        }
    }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn digits() {
        assert_eq!(digit_value(b'7' as u32, 10), Some(7));
        assert_eq!(digit_value(b'f' as u32, 16), Some(15));
        assert_eq!(digit_value(b'F' as u32, 16), Some(15));
        assert_eq!(digit_value(b'9' as u32, 8), None);
        assert_eq!(digit_value(b'@' as u32, 36), None);
    }
}

