258	    /// `PROC parse` ( c -- a n ): up to the next `c` (exclusive).
259	    fn parse(&mut self) -> R {
260	        let c = self.eax() as u8;
261	        let (start, end) = (self.var(st::TIN), self.var(st::TP));
262	        let mut p = start;
263	        while p < end && self.mem.read_u8(p)? != c {
264	            p += 1;
265	        }
266	        let len = p - start;
267	        self.setv(st::TIN, if p < end { p + 1 } else { end })?;
268	        self.set_eax(start);
269	        self.upsh(len)
270	    }
