272	    /// `PROC parse_with_escape` (`parse/`) ( c -- a n ): like `parse`, but
273	    /// `\x` stands for `x`; the result is copied to the parse buffer.
274	    fn parse_escaped(&mut self) -> R {
275	        let term = self.eax() as u8;
276	        let end = self.var(st::TP);
277	        let mut p = self.var(st::TIN);
278	        let mut out = PARSE_BUF;
279	        while p < end && out < PARSE_BUF + PARSE_BUF_SIZE {
280	            let mut c = self.mem.read_u8(p)?;
281	            p += 1;
282	            if c == b'\\' && p < end {
283	                c = self.mem.read_u8(p)?;
284	                p += 1;
285	            } else if c == term {
286	                break;
287	            }
288	            self.mem.write_u8(out, c)?;
289	            out += 1;
290	        }
291	        self.setv(st::TIN, p)?;
292	        self.set_eax(PARSE_BUF);
293	        self.upsh(out - PARSE_BUF)
294	    }
