296	    /// `PROC single`: `[-][#$%&]digits` or `'c`, in the current base.
297	    /// Overflow is an error, as in the original (`jo .err`).
298	    fn parse_single(&self, a: u32, n: u32) -> R<Option<u32>> {
299	        if n == 0 {
300	            return Ok(None);
301	        }
302	        let s = self.mem.slice(a, n)?;
303	        let mut base = self.var(st::BASE);
304	        let mut i = 0;
305	        let neg = s[0] == b'-';
306	        if neg {
307	            i = 1;
308	            if i == s.len() {
309	                return Ok(None);
310	            }
311	        }
312	        let sign = |v: u32| if neg { v.wrapping_neg() } else { v };
313	        if (b'#'..=b'\'').contains(&s[i]) {
314	            let k = (s[i] - b'#') as usize;
315	            if k == 4 {
316	                return Ok(s.get(i + 1).map(|&c| sign(c as u32)));
317	            }
318	            base = BASES[k];
319	            i += 1;
320	            if i == s.len() {
321	                return Ok(None);
322	            }
323	        }
324	        let mut acc = 0u32;
325	        for &c in &s[i..] {
326	            let Some(d) = digit_value(c as u32, base) else {
327	                return Ok(None);
328	            };
329	            let full = acc as u64 * base as u64;
330	            if full > u32::MAX as u64 {
331	                return Ok(None);
332	            }
333	            let (sum, overflow) = (full as u32 as i32).overflowing_add(d as i32);
334	            if overflow {
335	                return Ok(None);
336	            }
337	            acc = sum as u32;
338	        }
339	        Ok(Some(sign(acc)))
340	    }
