342	    /// `PROC double`: like `single` with a trailing `L`; `.` and `,` are
343	    /// ignored as digit separators; 64-bit wrap-around arithmetic.
344	    fn parse_double(&self, a: u32, n: u32) -> R<Option<(u32, u32)>> {
345	        if n < 2 {
346	            return Ok(None);
347	        }
348	        let s = self.mem.slice(a, n)?;
349	        if s[s.len() - 1] != b'L' {
350	            return Ok(None);
351	        }
352	        let s = &s[..s.len() - 1];
353	        let mut base = self.var(st::BASE) as u64;
354	        let mut i = 0;
355	        let neg = s[0] == b'-';
356	        if neg {
357	            i = 1;
358	            if i == s.len() {
359	                return Ok(None);
360	            }
361	        }
362	        if (b'#'..=b'&').contains(&s[i]) {
363	            base = BASES[(s[i] - b'#') as usize] as u64;
364	            i += 1;
365	            if i == s.len() {
366	                return Ok(None);
367	            }
368	        }
369	        let mut acc = 0u64;
370	        for &c in &s[i..] {
371	            if c == b'.' || c == b',' {
372	                continue;
373	            }
374	            let Some(d) = digit_value(c as u32, base as u32) else {
375	                return Ok(None);
376	            };
377	            acc = acc.wrapping_mul(base).wrapping_add(d as u64);
378	        }
379	        if neg {
380	            acc = acc.wrapping_neg();
381	        }
382	        Ok(Some((acc as u32, (acc >> 32) as u32)))
383	    }
