461	    /// `PROC link` ( dataptr listptr -- ): push a node `[prior][dataptr]`
462	    /// built at `here` onto the front of the list.
463	    fn link(&mut self) -> R {
464	        let listptr = self.upop()?;
465	        let data = self.upop()?;
466	        let h = self.reserve_code(8)?;
467	        let prior = self.mem.read_u32(listptr)?;
468	        self.mem.write_u32(listptr, h)?;
469	        self.mem.write_u32(h, prior)?;
470	        self.mem.write_u32(h + 4, data)?;
471	        self.setv(st::H, h + 8)
472	    }
