488	    /// `PROC iterate`: call `xt` with each node's data address until it
489	    /// returns 0.  Runs as nested calls.
490	    fn iterate_list(&mut self, host: &mut dyn Host, xt: u32, list: u32) -> R {
491	        if xt == 0 {
492	            return Ok(());
493	        }
494	        let mut node = list;
495	        loop {
496	            node = self.mem.read_u32(node)?;
497	            if node == 0 {
498	                return Ok(());
499	            }
500	            self.upsh(node + 4)?;
501	            self.call_nested(host, xt)?;
502	            if self.upop()? == 0 {
