535	    /// `PROC _slurp` ( a n -- a' n' ): read a whole file into the heap.
536	    /// Failure leaves ( 0 0 ), sets `ioerr` and CF.
537	    fn slurp(&mut self, host: &mut dyn Host) -> R<bool> {
538	        let n = self.eax();
539	        let a = self.nos()?;
540	        let path = String::from_utf8_lossy(self.mem.slice(a, n)?).into_owned();
541	        let bytes = host
