586	    /// One key of `query`'s line editor.  `None` means "keep reading".
587	    fn query_char(&mut self, c: u32) -> R<Option<Next>> {
588	        let tp = self.var(st::TP);
589	        if c == EOF_KEY {
590	            // Deviation: newcore exited at once, losing a final line that
591	            // had no newline.  Interpret that line first; the next EOF exits.
592	            if tp > TIB {
593	                return Ok(Some(Next::Jump(Gate::InterpWord.addr())));
594	            }
595	            self.upsh(0)?;
596	            return Ok(Some(Next::Jump(Gate::Bye.addr())));
597	        }
598	        if c == u32::MAX {
599	            return Ok(Some(Next::Jump(Gate::Interpret.addr())));
600	        }
601	        match c as u8 {
602	            b'\n' => return Ok(Some(Next::Jump(Gate::InterpWord.addr()))),
603	            b'\r' => {}
604	            8 => self.setv(st::TP, if tp > TIB { tp - 1 } else { TIB })?,
605	            ch => {
606	                self.mem.write_u8(tp, if ch == b'\t' { b' ' } else { ch })?;
607	                self.setv(st::TP, tp + 1)?;
608	                if tp + 1 >= TIB_TOP {
609	                    return Ok(Some(Next::Jump(Gate::InterpWord.addr())));
610	                }
611	            }
612	        }
613	        Ok(None)
614	    }
