616	    /// `interpret`'s `.afterok`: `ecx` is the token kind + 1 from the
617	    /// tokenizer (1 = dictionary entry, 2 = single, 3 = double).
618	    fn after_ok(&mut self, ecx: u32) -> R<Next> {
619	        let kind = ecx.wrapping_sub(1);
620	        if kind == 0 {
621	            let entry = self.eax();
622	            let class = self.mem.read_u32(entry.wrapping_sub(4))?;
623	            self.cpu.r[EDX as usize] = entry;
624	            self.cpu.r[EDI as usize] = class;
625	            self.set_eax(self.mem.read_u32(entry.wrapping_add(4))?);
626	            return Ok(Next::Call(class, Gate::InterpWord));
627	        }
628	        if self.compiling() {
629	            match kind {
630	                1 => {
631	                    let v = self.upop()?;
632	                    self.compile_literal(v)?;
633	                }
634	                2 => {
635	                    let hi = self.upop()?;
636	                    let lo = self.upop()?;
637	                    self.compile_literal(lo)?;
638	                    self.compile_literal(hi)?;
639	                }
640	                _ => {}
641	            }
642	        }
643	        Ok(Next::Jump(Gate::InterpWord.addr()))
