                let r = self.zpath(a[0]).and_then(|p| {
                    with_fs(host, |fs| match num {
                        SYS_UNLINK => fs.remove(&p),
                        SYS_CHDIR => fs.chdir(&p),
                        SYS_MKDIR => fs.mkdir(&p),
                        _ => fs.rmdir(&p),
                    })
                });
