1	//! Executor: apply one [`Insn`] to [`Cpu`] + [`Memory`].
2	//!
3	//! Flags follow the Intel SDM for every instruction in the subset, except AF
4	//! (not modelled) and the "undefined" flag results, which are left as the
5	//! nearest sensible value.  Reva code tests ZF, CF, SF and OF (`jz`, `jc`,
6	//! `sbb eax,eax`, `jle`) and occasionally PF.
7	
8	use super::*;
9	use crate::fault::Fault;
10	use crate::mem::Memory;
11	
12	impl Cpu {
13	    #[inline]
14	    pub fn ea(&self, m: &MemRef) -> u32 {
15	        let mut a = m.disp;
16	        if let Some(b) = m.base {
17	            a = a.wrapping_add(self.r[b as usize]);
18	        }
19	        if let Some(i) = m.index {
20	            a = a.wrapping_add(self.r[i as usize].wrapping_mul(m.scale as u32));
21	        }
22	        a
23	    }
24	
25	    #[inline]
26	    pub fn get_reg(&self, n: u8, size: Size) -> u32 {
27	        let n = n as usize;
28	        match size {
29	            Size::D => self.r[n],
30	            Size::W => self.r[n] & 0xffff,
31	            Size::B if n < 4 => self.r[n] & 0xff,
32	            Size::B => (self.r[n - 4] >> 8) & 0xff,
33	        }
34	    }
35	
36	    #[inline]
37	    pub fn set_reg(&mut self, n: u8, size: Size, v: u32) {
38	        let n = n as usize;
39	        match size {
40	            Size::D => self.r[n] = v,
41	            Size::W => self.r[n] = (self.r[n] & 0xffff_0000) | (v & 0xffff),
42	            Size::B if n < 4 => self.r[n] = (self.r[n] & !0xff) | (v & 0xff),
43	            Size::B => self.r[n - 4] = (self.r[n - 4] & !0xff00) | ((v & 0xff) << 8),
44	        }
45	    }
46	
47	    #[inline]
48	    fn read(&self, mem: &Memory, o: Opd, size: Size) -> Result<u32, Fault> {
49	        match o {
50	            Opd::Reg(n) => Ok(self.get_reg(n, size)),
51	            Opd::Imm(v) => Ok(v & size.mask()),
52	            Opd::Mem(m) => {
53	                let a = self.ea(&m);
54	                match size {
55	                    Size::B => mem.read_u8(a).map(u32::from),
56	                    Size::W => mem.read_u16(a).map(u32::from),
57	                    Size::D => mem.read_u32(a),
58	                }
59	            }
60	        }
61	    }
62	
63	    #[inline]
64	    fn write(&mut self, mem: &mut Memory, o: Opd, size: Size, v: u32) -> Result<(), Fault> {
65	        match o {
66	            Opd::Reg(n) => {
67	                self.set_reg(n, size, v);
68	                Ok(())
69	            }
70	            Opd::Mem(m) => {
71	                let a = self.ea(&m);
72	                match size {
73	                    Size::B => mem.write_u8(a, v as u8),
74	                    Size::W => mem.write_u16(a, v as u16),
75	                    Size::D => mem.write_u32(a, v),
76	                }
77	            }
78	            Opd::Imm(_) => Err(Fault::Trap {
79	                eip: self.eip,
80	                what: "write to immediate",
81	            }),
82	        }
83	    }
84	
85	    #[inline]
86	    fn set_szp(&mut self, r: u32, size: Size) {
87	        self.zf = r & size.mask() == 0;
88	        self.sf = r & size.sign() != 0;
89	        self.pf = (r as u8).count_ones().is_multiple_of(2);
90	    }
91	
92	    /// The eight ALU operations with full flag semantics.
93	    pub fn alu(&mut self, op: Alu, size: Size, a: u32, b: u32) -> u32 {
94	        let (m, s) = (size.mask(), size.sign());
95	        let (a, b) = (a & m, b & m);
96	        let r = match op {
97	            Alu::Add | Alu::Adc => {
98	                let c = (op == Alu::Adc && self.cf) as u64;
99	                let full = a as u64 + b as u64 + c;
100	                let r = full as u32 & m;
101	                self.cf = full > m as u64;
102	                self.of = (a ^ r) & (b ^ r) & s != 0;
103	                r
104	            }
105	            Alu::Sub | Alu::Sbb | Alu::Cmp => {
106	                let c = (op == Alu::Sbb && self.cf) as u32;
107	                let r = a.wrapping_sub(b).wrapping_sub(c) & m;
108	                self.cf = (a as u64) < b as u64 + c as u64;
109	                self.of = (a ^ b) & (a ^ r) & s != 0;
110	                r
111	            }
112	            Alu::And | Alu::Or | Alu::Xor => {
113	                self.cf = false;
114	                self.of = false;
115	                match op {
116	                    Alu::And => a & b,
117	                    Alu::Or => a | b,
118	                    _ => a ^ b,
119	                }
120	            }
121	        };
122	        self.set_szp(r, size);
123	        r
124	    }
125	
126	    #[inline]
127	    pub fn push32(&mut self, mem: &mut Memory, v: u32) -> Result<(), Fault> {
128	        let sp = self.r[ESP as usize].wrapping_sub(4);
129	        if sp < self.esp_floor {
130	            return Err(Fault::ReturnStackOverflow);
131	        }
132	        mem.write_u32(sp, v)?;
133	        self.r[ESP as usize] = sp;
134	        Ok(())
135	    }
136	
137	    #[inline]
138	    pub fn pop32(&mut self, mem: &Memory) -> Result<u32, Fault> {
139	        let sp = self.r[ESP as usize];
140	        let v = mem.read_u32(sp)?;
141	        self.r[ESP as usize] = sp.wrapping_add(4);
142	        Ok(v)
143	    }
144	
145	    fn shift(&mut self, op: Shift, size: Size, v: u32, cnt: u32) -> u32 {
146	        let bits = size.bytes() * 8;
147	        let (m, s) = (size.mask(), size.sign());
148	        let v = v & m;
149	        match op {
150	            Shift::Shl => {
151	                let full = (v as u64) << cnt;
152	                let r = full as u32 & m;
153	                self.cf = (full >> bits) & 1 != 0;
154	                self.of = (r & s != 0) != self.cf;
155	                self.set_szp(r, size);
156	                r
157	            }
158	            Shift::Shr => {
159	                let r = ((v as u64) >> cnt) as u32;
160	                self.cf = ((v as u64) >> (cnt - 1)) & 1 != 0;
161	                self.of = v & s != 0;
162	                self.set_szp(r, size);
163	                r
164	            }
165	            Shift::Sar => {
166	                let sv = if v & s != 0 {
167	                    (v as i64) - ((m as i64) + 1)
168	                } else {
169	                    v as i64
170	                };
171	                let r = (sv >> cnt.min(63)) as u32 & m;
172	                self.cf = (sv >> (cnt - 1).min(63)) & 1 != 0;
173	                self.of = false;
174	                self.set_szp(r, size);
175	                r
176	            }
177	            Shift::Rol | Shift::Ror => {
178	                let c = cnt % bits;
179	                let r = if c == 0 {
180	                    v
181	                } else if op == Shift::Rol {
182	                    ((v << c) | (v >> (bits - c))) & m
183	                } else {
184	                    ((v >> c) | (v << (bits - c))) & m
185	                };
186	                if op == Shift::Rol {
187	                    self.cf = r & 1 != 0;
188	                    self.of = (r & s != 0) != self.cf;
189	                } else {
190	                    self.cf = r & s != 0;
191	                    self.of = (r & s != 0) != (r & (s >> 1) != 0);
192	                }
193	                r
194	            }
195	            Shift::Rcl | Shift::Rcr => {
196	                let mut r = v;
197	                for _ in 0..cnt % (bits + 1) {
198	                    if op == Shift::Rcl {
199	                        let out = r & s != 0;
200	                        r = ((r << 1) | self.cf as u32) & m;
201	                        self.cf = out;
202	                    } else {
203	                        let out = r & 1 != 0;
204	                        r = (r >> 1) | if self.cf { s } else { 0 };
205	                        self.cf = out;
206	                    }
207	                }
208	                self.of = if op == Shift::Rcl {
209	                    (r & s != 0) != self.cf
210	                } else {
211	                    (r & s != 0) != (r & (s >> 1) != 0)
212	                };
213	                r
214	            }
215	        }
216	    }
217	
218	    fn muldiv(&mut self, op: MulDiv, size: Size, src: u32, at: u32) -> Result<(), Fault> {
219	        let err = Fault::DivideError { eip: at };
220	        let bits = size.bytes() * 8;
221	        let m = size.mask() as u64;
222	        // Accumulator pair: AX for bytes (AL/AH), DX:AX, EDX:EAX.
223	        let (lo, hi) = match size {
224	            Size::B => (self.r[0] & 0xff, (self.r[0] >> 8) & 0xff),
225	            Size::W => (self.r[0] & 0xffff, self.r[2] & 0xffff),
226	            Size::D => (self.r[0], self.r[2]),
227	        };
228	        let sext = |v: u64, b: u32| -> i64 { ((v << (64 - b)) as i64) >> (64 - b) };
229	        let (q, r) = match op {
230	            MulDiv::Mul => {
231	                let p = lo as u64 * src as u64;
232	                let (q, r) = (p & m, (p >> bits) & m);
233	                self.cf = r != 0;
234	                self.of = r != 0;
235	                (q, r)
236	            }
237	            MulDiv::Imul => {
238	                let p = sext(lo as u64, bits) * sext(src as u64, bits);
239	                let fits = sext(p as u64 & m, bits) == p;
240	                self.cf = !fits;
241	                self.of = !fits;
242	                (p as u64 & m, (p as u64 >> bits) & m)
243	            }
244	            MulDiv::Div => {
245	                let n = ((hi as u64) << bits) | lo as u64;
246	                if src == 0 {
247	                    return Err(err);
248	                }
249	                let q = n / src as u64;
250	                if q > m {
251	                    return Err(err);
252	                }
253	                (q, n % src as u64)
254	            }
255	            MulDiv::Idiv => {
256	                let n = sext(((hi as u64) << bits) | lo as u64, bits * 2);
257	                let d = sext(src as u64, bits);
258	                let q = n.checked_div(d).ok_or(err.clone())?;
259	                if sext(q as u64 & m, bits) != q {
260	                    return Err(err);
261	                }
262	                (q as u64 & m, (n % d) as u64 & m)
263	            }
264	        };
265	        match size {
266	            Size::B => self.set_reg(EAX, Size::W, (q as u32) | ((r as u32) << 8)),
267	            Size::W => {
268	                self.set_reg(EAX, Size::W, q as u32);
269	                self.set_reg(EDX, Size::W, r as u32);
270	            }
271	            Size::D => {
272	                self.r[0] = q as u32;
273	                self.r[2] = r as u32;
274	            }
275	        }
276	        Ok(())
277	    }
278	
279	    fn string_once(&mut self, mem: &mut Memory, op: StrOp, size: Size) -> Result<(), Fault> {
280	        let n = size.bytes();
281	        let step = if self.df { n.wrapping_neg() } else { n };
282	        let (si, di) = (ESI as usize, EDI as usize);
283	        let rd = |mem: &Memory, a: u32| -> Result<u32, Fault> {
284	            match size {
285	                Size::B => mem.read_u8(a).map(u32::from),
286	                Size::W => mem.read_u16(a).map(u32::from),
287	                Size::D => mem.read_u32(a),
288	            }
289	        };
290	        let wr = |mem: &mut Memory, a: u32, v: u32| -> Result<(), Fault> {
291	            match size {
292	                Size::B => mem.write_u8(a, v as u8),
293	                Size::W => mem.write_u16(a, v as u16),
294	                Size::D => mem.write_u32(a, v),
295	            }
296	        };
297	        match op {
298	            StrOp::Lods => {
299	                let v = rd(mem, self.r[si])?;
300	                self.set_reg(EAX, size, v);
301	                self.r[si] = self.r[si].wrapping_add(step);
302	            }
303	            StrOp::Stos => {
304	                wr(mem, self.r[di], self.get_reg(EAX, size))?;
305	                self.r[di] = self.r[di].wrapping_add(step);
306	            }
307	            StrOp::Movs => {
308	                let v = rd(mem, self.r[si])?;
309	                wr(mem, self.r[di], v)?;
310	                self.r[si] = self.r[si].wrapping_add(step);
311	                self.r[di] = self.r[di].wrapping_add(step);
312	            }
313	            StrOp::Scas => {
314	                let b = rd(mem, self.r[di])?;
315	                self.alu(Alu::Cmp, size, self.get_reg(EAX, size), b);
316	                self.r[di] = self.r[di].wrapping_add(step);
317	            }
318	            StrOp::Cmps => {
319	                let a = rd(mem, self.r[si])?;
320	                let b = rd(mem, self.r[di])?;
321	                self.alu(Alu::Cmp, size, a, b);
322	                self.r[si] = self.r[si].wrapping_add(step);
323	                self.r[di] = self.r[di].wrapping_add(step);
324	            }
325	        }
326	        Ok(())
327	    }
