329	    /// Execute `insn`, which was decoded at `self.eip`.
330	    pub fn exec(&mut self, mem: &mut Memory, insn: &Insn) -> Result<(), Fault> {
331	        let at = self.eip;
332	        let next = at.wrapping_add(insn.len as u32);
333	        self.eip = next;
334	        match insn.op {
335	            Op::Alu { op, size, dst, src } => {
336	                let a = self.read(mem, dst, size)?;
337	                let b = self.read(mem, src, size)?;
338	                let r = self.alu(op, size, a, b);
339	                if op != Alu::Cmp {
340	                    self.write(mem, dst, size, r)?;
341	                }
342	            }
343	            Op::Test { size, a, b } => {
344	                let x = self.read(mem, a, size)?;
345	                let y = self.read(mem, b, size)?;
346	                self.alu(Alu::And, size, x, y);
347	            }
348	            Op::Mov { size, dst, src } => {
349	                let v = self.read(mem, src, size)?;
350	                self.write(mem, dst, size, v)?;
351	            }
352	            Op::Movx {
353	                signed,
354	                from,
355	                dst,
356	                src,
357	            } => {
358	                let v = self.read(mem, src, from)?;
359	                self.r[dst as usize] = if signed && v & from.sign() != 0 {
360	                    v | !from.mask()
361	                } else {
362	                    v
363	                };
364	            }
365	            Op::Lea { dst, mem: m } => self.r[dst as usize] = self.ea(&m),
366	            Op::Xchg { size, a, b } => {
367	                let x = self.read(mem, a, size)?;
368	                let y = self.read(mem, b, size)?;
369	                self.write(mem, a, size, y)?;
370	                self.write(mem, b, size, x)?;
371	            }
372	            Op::Inc { size, dst } | Op::Dec { size, dst } => {
373	                let v = self.read(mem, dst, size)?;
374	                let c = self.cf;
375	                let op = if matches!(insn.op, Op::Inc { .. }) {
376	                    Alu::Add
377	                } else {
378	                    Alu::Sub
379	                };
380	                let r = self.alu(op, size, v, 1);
381	                self.cf = c;
382	                self.write(mem, dst, size, r)?;
383	            }
384	            Op::Not { size, dst } => {
385	                let v = self.read(mem, dst, size)?;
386	                self.write(mem, dst, size, !v)?;
387	            }
388	            Op::Neg { size, dst } => {
389	                let v = self.read(mem, dst, size)?;
390	                let r = self.alu(Alu::Sub, size, 0, v);
391	                self.write(mem, dst, size, r)?;
392	            }
393	            Op::Push(o) => {
394	                let v = self.read(mem, o, Size::D)?;
395	                self.push32(mem, v)?;
396	            }
397	            Op::Pop(o) => {
398	                let v = self.pop32(mem)?;
399	                self.write(mem, o, Size::D, v)?;
400	            }
401	            Op::Shift {
402	                op,
403	                size,
404	                dst,
405	                count,
406	            } => {
407	                let cnt = self.read(mem, count, Size::B)? & 0x1f;
408	                if cnt != 0 {
409	                    let v = self.read(mem, dst, size)?;
410	                    let r = self.shift(op, size, v, cnt);
411	                    self.write(mem, dst, size, r)?;
412	                }
413	            }
414	            Op::MulDiv { op, size, src } => {
415	                let s = self.read(mem, src, size)?;
416	                self.muldiv(op, size, s, at)?;
417	            }
418	            Op::Imul { dst, src, imm } => {
419	                let s = self.read(mem, src, Size::D)? as i32 as i64;
420	                let o = match imm {
421	                    Some(i) => i as i32 as i64,
422	                    None => self.r[dst as usize] as i32 as i64,
423	                };
424	                let p = s * o;
425	                let fits = p == p as i32 as i64;
426	                self.cf = !fits;
427	                self.of = !fits;
428	                self.r[dst as usize] = p as u32;
429	            }
430	            Op::Cdq => {
431	                self.r[2] = if self.r[0] & 0x8000_0000 != 0 {
432	                    u32::MAX
433	                } else {
434	                    0
435	                }
436	            }
437	            Op::Cwde => self.r[0] = self.r[0] as u16 as i16 as i32 as u32,
438	            Op::Cbw => {
439	                self.r[0] =
440	                    (self.r[0] & 0xffff_0000) | u32::from(self.r[0] as u8 as i8 as i16 as u16)
441	            }
442	            Op::Cwd => {
443	                let high = if self.r[0] & 0x8000 != 0 { 0xffff } else { 0 };
444	                self.r[2] = (self.r[2] & 0xffff_0000) | high;
445	            }
446	            Op::Str { op, size, rep } => match rep {
447	                Rep::None => self.string_once(mem, op, size)?,
448	                _ => {
449	                    let cmp = matches!(op, StrOp::Scas | StrOp::Cmps);
450	                    while self.r[ECX as usize] != 0 {
451	                        self.string_once(mem, op, size)?;
452	                        self.r[ECX as usize] -= 1;
453	                        if cmp && ((rep == Rep::E && !self.zf) || (rep == Rep::Ne && self.zf)) {
454	                            break;
455	                        }
456	                    }
457	                }
458	            },
459	            Op::Jcc { cc, target } => {
460	                if self.cond(cc) {
461	                    self.eip = target;
462	                }
463	            }
464	            Op::Setcc { cc, dst } => {
465	                let v = self.cond(cc) as u32;
466	                self.write(mem, dst, Size::B, v)?;
467	            }
468	            Op::Bswap(r) => self.r[r as usize] = self.r[r as usize].swap_bytes(),
469	            Op::Cmovcc { cc, dst, src } => {
470	                let v = self.read(mem, src, Size::D)?;
471	                if self.cond(cc) {
472	                    self.r[dst as usize] = v;
473	                }
474	            }
475	            Op::Jmp(t) => self.eip = t,
476	            Op::JmpInd(o) => self.eip = self.read(mem, o, Size::D)?,
477	            Op::Call(t) => {
478	                self.push32(mem, next)?;
479	                self.eip = t;
480	            }
481	            Op::CallInd(o) => {
482	                let t = self.read(mem, o, Size::D)?;
483	                self.push32(mem, next)?;
484	                self.eip = t;
485	            }
486	            Op::Ret(n) => {
487	                self.eip = self.pop32(mem)?;
488	                self.r[ESP as usize] = self.r[ESP as usize].wrapping_add(n as u32);
489	            }
490	            Op::Loop { kind, target } => {
491	                let c = &mut self.r[ECX as usize];
492	                let take = match kind {
493	                    LoopKind::Jecxz => *c == 0,
494	                    _ => {
495	                        *c = c.wrapping_sub(1);
496	                        *c != 0
497	                            && match kind {
498	                                LoopKind::Loope => self.zf,
499	                                LoopKind::Loopne => !self.zf,
500	                                _ => true,
501	                            }
502	                    }
503	                };
504	                if take {
505	                    self.eip = target;
506	                }
507	            }
508	            Op::Flag(f) => match f {
509	                FlagOp::Clc => self.cf = false,
510	                FlagOp::Stc => self.cf = true,
511	                FlagOp::Cmc => self.cf = !self.cf,
512	                FlagOp::Cld => self.df = false,
513	                FlagOp::Std => self.df = true,
514	            },
515	            Op::Nop => {}
516	            Op::Hlt => {
517	                return Err(Fault::Trap {
518	                    eip: at,
519	                    what: "hlt",
520	                });
521	            }
522	            Op::Int3 => {
523	                return Err(Fault::Trap {
524	                    eip: at,
525	                    what: "int3 breakpoint",
526	                });
527	            }
528	            Op::Fpu(f) => self.fpu_exec(mem, f)?,
529	        }
530	        Ok(())
531	    }
532	}
