267	/// `f64` → the x87 80-bit format (exact).
268	pub fn f64_to_f80(v: f64) -> [u8; 10] {
269	    let bits = v.to_bits();
270	    let sign = ((bits >> 63) as u16) << 15;
271	    let exp = ((bits >> 52) & 0x7ff) as i32;
272	    let frac = bits & ((1 << 52) - 1);
273	    let (e, m) = match exp {
274	        0x7ff => (0x7fff, (1 << 63) | (frac << 11)),
275	        0 if frac == 0 => (0, 0),
276	        0 => {
277	            // f64 subnormal: normal in the wider exponent range
278	            let shift = frac.leading_zeros();
279	            ((16383 - 1074 + 63 - shift as i32) as u16, frac << shift)
280	        }
281	        _ => ((exp - 1023 + 16383) as u16, (1 << 63) | (frac << 11)),
282	    };
283	    let mut out = [0; 10];
284	    out[..8].copy_from_slice(&m.to_le_bytes());
285	    out[8..].copy_from_slice(&(sign | e).to_le_bytes());
286	    out
287	}
288	
289	/// `m >> sh`, rounded to nearest, ties to even.
290	fn shr_round(m: u64, sh: u32) -> u64 {
291	    match sh {
292	        0 => m,
293	        1..=63 => {
294	            let (q, rem, half) = (m >> sh, m & ((1 << sh) - 1), 1u64 << (sh - 1));
295	            q + u64::from(rem > half || (rem == half && q & 1 == 1))
296	        }
297	        64 => u64::from(m > 1 << 63),
298	        _ => 0,
299	    }
300	}
301	
302	/// The x87 80-bit format → `f64`, rounded to nearest-even.
303	pub fn f80_to_f64(b: &[u8; 10]) -> f64 {
304	    let m = u64::from_le_bytes(b[..8].try_into().unwrap());
305	    let se = u16::from_le_bytes([b[8], b[9]]);
306	    let sign = u64::from(se >> 15) << 63;
307	    let e = i32::from(se & 0x7fff);
308	    if e == 0x7fff {
309	        if m << 1 == 0 {
310	            return f64::from_bits(sign | (0x7ff << 52));
311	        }
312	        let frac = ((m >> 11) & ((1 << 52) - 1)).max(1);
313	        return f64::from_bits(sign | (0x7ff << 52) | frac | (1 << 51));
314	    }
315	    if m == 0 {
316	        return f64::from_bits(sign);
317	    }
318	    // value = m * 2^(e' - 16383 - 63), e' = 1 for denormals
319	    let lz = m.leading_zeros();
320	    let m = m << lz;
321	    let mut exp2 = e.max(1) - 16383 - lz as i32; // m now has its top bit set
322	    if exp2 >= -1022 {
323	        let mut q = shr_round(m, 11);
324	        if q == 1 << 53 {
325	            q >>= 1;
326	            exp2 += 1;
327	        }
328	        if exp2 > 1023 {
329	            return f64::from_bits(sign | (0x7ff << 52));
330	        }
331	        f64::from_bits(sign | (((exp2 + 1023) as u64) << 52) | (q & ((1 << 52) - 1)))
332	    } else {
333	        // subnormal in f64 (a carry into bit 52 is the smallest normal)
334	        let sh = (-1011 - exp2) as u32;
335	        f64::from_bits(sign | shr_round(m, sh))
336	    }
337	}
338	
339	/// `v * 2^n` without overflowing the intermediate power.
340	fn ldexp(mut v: f64, mut n: i64) -> f64 {
341	    let step = |k: i64| f64::from_bits(((k + 1023) as u64) << 52);
342	    while n > 1000 {
343	        v *= step(1000);
344	        n -= 1000;
345	        if v.is_infinite() {
346	            return v;
347	        }
348	    }
349	    while n < -1000 {
350	        v *= step(-1000);
351	        n += 1000;
352	        if v == 0.0 {
353	            return v;
354	        }
355	    }
356	    v * step(n)
357	}
358	
359	/// `(significand in [1, 2), unbiased exponent)` of a finite non-zero value.
360	fn split(v: f64) -> (f64, i64) {
361	    let bits = v.to_bits();
362	    let exp = ((bits >> 52) & 0x7ff) as i64;
363	    if exp == 0 {
364	        let (s, e) = split(v * f64::from_bits((1023 + 64) << 52));
365	        return (s, e - 64);
366	    }
367	    let sig = f64::from_bits((bits & !(0x7ff << 52)) | (1023 << 52));
368	    (sig, exp - 1023)
369	}
