371	/// Condition codes of a comparison: (C3, C2, C0).
372	fn compare(a: f64, b: f64) -> (bool, bool, bool) {
373	    if a.is_nan() || b.is_nan() {
374	        (true, true, true)
375	    } else if a > b {
376	        (false, false, false)
377	    } else if a < b {
378	        (false, false, true)
379	    } else {
380	        (true, false, false)
381	    }
382	}
