//! # VM memory
//!
//! One `Vec<u8>` addressed by `u32`.  All accesses are bounds-checked and the
//! null guard faults, so a wild pointer in Forth code produces a [`Fault`]
//! instead of undefined behaviour in the host.
//!
//! ## Self-modifying code
//!
//! Reva patches code it has already emitted (`then` back-patches jumps, `;`
//! turns a trailing `call` into a `jmp`, `does>` rewrites a word's class).
//! Anything that caches decoded or translated code must therefore learn about
//! writes to code it has seen.  Memory keeps a bitmap of *code pages*
//! (256 bytes each); the decoder marks a page when it decodes an instruction
//! there, and any write into a marked page clears the mark and queues the page
//! on the *dirty list*.  Caches drain that list before their next lookup.
//! Writes to plain data pages cost one bit test.

use crate::fault::Fault;
use crate::layout::NULL_GUARD;

pub const PAGE_SHIFT: u32 = 8;
pub const PAGE_SIZE: u32 = 1 << PAGE_SHIFT;

pub struct Memory {
    bytes: Vec<u8>,
    code_pages: Vec<u64>,
    dirty: Vec<u32>,
}

impl Memory {
    pub fn new(size: u32) -> Memory {
        let pages = (size >> PAGE_SHIFT) as usize + 1;
        Memory {
            bytes: vec![0; size as usize],
            code_pages: vec![0; pages.div_ceil(64)],
            dirty: Vec::new(),
        }
    }

    pub fn size(&self) -> u32 {
        self.bytes.len() as u32
    }

    #[inline]
    fn range(&self, addr: u32, len: u32) -> Result<std::ops::Range<usize>, Fault> {
        let end = addr as u64 + len as u64;
        if addr < NULL_GUARD || end > self.bytes.len() as u64 {
            return Err(Fault::BadAddress { addr, len });
        }
        Ok(addr as usize..end as usize)
    }

    #[inline]
    pub fn read_u8(&self, addr: u32) -> Result<u8, Fault> {
        let r = self.range(addr, 1)?;
        Ok(self.bytes[r.start])
    }

    #[inline]
    pub fn read_u16(&self, addr: u32) -> Result<u16, Fault> {
        let r = self.range(addr, 2)?;
        Ok(u16::from_le_bytes([
            self.bytes[r.start],
            self.bytes[r.start + 1],
        ]))
    }

    #[inline]
    pub fn read_u32(&self, addr: u32) -> Result<u32, Fault> {
        let r = self.range(addr, 4)?;
        let b = &self.bytes[r];
        Ok(u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
    }

    #[inline]
    pub fn write_u8(&mut self, addr: u32, v: u8) -> Result<(), Fault> {
        let r = self.range(addr, 1)?;
        self.note_write(addr, 1);
        self.bytes[r.start] = v;
        Ok(())
    }

    #[inline]
    pub fn write_u16(&mut self, addr: u32, v: u16) -> Result<(), Fault> {
        let r = self.range(addr, 2)?;
        self.note_write(addr, 2);
        self.bytes[r].copy_from_slice(&v.to_le_bytes());
        Ok(())
    }

    #[inline]
    pub fn write_u32(&mut self, addr: u32, v: u32) -> Result<(), Fault> {
        let r = self.range(addr, 4)?;
        self.note_write(addr, 4);
        self.bytes[r].copy_from_slice(&v.to_le_bytes());
        Ok(())
    }

    pub fn slice(&self, addr: u32, len: u32) -> Result<&[u8], Fault> {
        let r = self.range(addr, len)?;
        Ok(&self.bytes[r])
    }

    pub fn write_bytes(&mut self, addr: u32, data: &[u8]) -> Result<(), Fault> {
        let r = self.range(addr, data.len() as u32)?;
        self.note_write(addr, data.len() as u32);
        self.bytes[r].copy_from_slice(data);
        Ok(())
    }

    /// Byte-at-a-time forward copy, exactly like Reva's `_move` (so an
    /// overlapping copy to a higher address smears, as it always did).
    pub fn move_forward(&mut self, src: u32, dst: u32, len: u32) -> Result<(), Fault> {
        if len == 0 {
            return Ok(());
        }
        self.range(src, len)?;
        let r = self.range(dst, len)?;
        self.note_write(dst, len);
        let (s, d) = (src as usize, r.start);
        if d <= s || d >= s + len as usize {
            self.bytes.copy_within(s..s + len as usize, d);
        } else {
            for i in 0..len as usize {
                self.bytes[d + i] = self.bytes[s + i];
            }
        }
        Ok(())
    }

    pub fn fill(&mut self, addr: u32, len: u32, v: u8) -> Result<(), Fault> {
        let r = self.range(addr, len)?;
        self.note_write(addr, len);
        self.bytes[r].fill(v);
        Ok(())
    }

    /// Raw view of the whole memory (for images and translators).
    pub fn as_bytes(&self) -> &[u8] {
        &self.bytes
    }

    // ---- code-page tracking -------------------------------------------

    #[inline]
    pub fn mark_code(&mut self, addr: u32) {
        let p = (addr >> PAGE_SHIFT) as usize;
        if let Some(w) = self.code_pages.get_mut(p / 64) {
            *w |= 1 << (p % 64);
        }
    }

    #[inline]
    fn note_write(&mut self, addr: u32, len: u32) {
        let first = addr >> PAGE_SHIFT;
        let last = (addr + len - 1) >> PAGE_SHIFT;
        for p in first..=last {
            let (w, bit) = ((p / 64) as usize, 1u64 << (p % 64));
            if self.code_pages[w] & bit != 0 {
                self.code_pages[w] &= !bit;
                self.dirty.push(p << PAGE_SHIFT);
            }
        }
    }

    /// True when code pages were written since the last [`Self::take_dirty`].
    #[inline]
    pub fn has_dirty(&self) -> bool {
        !self.dirty.is_empty()
    }

    /// Start addresses of code pages written since the last call.
    pub fn take_dirty(&mut self) -> Vec<u32> {
        std::mem::take(&mut self.dirty)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn null_guard_and_bounds() {
        let mut m = Memory::new(0x2000);
        assert!(m.read_u32(0).is_err());
        assert!(m.read_u32(0x1ffd).is_err());
        m.write_u32(0x1ffc, 0xdeadbeef).unwrap();
        assert_eq!(m.read_u32(0x1ffc).unwrap(), 0xdeadbeef);
        assert_eq!(m.read_u8(0x1fff).unwrap(), 0xde);
    }

    #[test]
    fn writes_to_code_pages_are_reported_once() {
        let mut m = Memory::new(0x4000);
        m.write_u8(0x1100, 1).unwrap();
        assert!(!m.has_dirty());
        m.mark_code(0x1100);
        m.write_u32(0x11fe, 7).unwrap(); // spans pages 0x1100 and 0x1200
        assert_eq!(m.take_dirty(), vec![0x1100]);
        m.write_u8(0x1100, 2).unwrap();
        assert!(!m.has_dirty());
    }

    #[test]
    fn overlapping_forward_move_smears_like_reva() {
        let mut m = Memory::new(0x2000);
        m.write_bytes(0x1000, b"ab....").unwrap();
        m.move_forward(0x1000, 0x1002, 4).unwrap();
        assert_eq!(m.slice(0x1000, 6).unwrap(), b"ababab");
    }
}
//! Faults: everything that can stop a VM step.
//!
//! The original core relied on the OS to deliver SIGSEGV/SIGFPE and then
//! jumped to the `exception` vector.  The portable core detects the same
//! conditions explicitly and reports them with enough context (address,
//! instruction bytes, routine name) to find the cause.

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Fault {
    /// Memory access outside VM memory or inside the null guard.
    BadAddress { addr: u32, len: u32 },
    /// An instruction outside the supported IA-32 subset.
    BadOpcode { eip: u32, bytes: Vec<u8> },
    /// `div`/`idiv` by zero or with a quotient that does not fit.
    DivideError { eip: u32 },
    /// Execution reached a gateway slot with no routine behind it.
    BadGate { addr: u32 },
    /// Execution of `hlt` or `int3`.
    Trap { eip: u32, what: &'static str },
    /// The data stack pointer moved above `S0`.
    StackUnderflow,
    /// `push`/`call` would move ESP below the return-stack region.
    ReturnStackOverflow,
    /// A core word that this port does not provide yet.
    NotImplemented(&'static str),
    /// A nested call (from a Rust routine into Forth) needed input that the
    /// host could not supply synchronously.
    InputInNestedCall,
    /// `throw` unwound past a Rust routine that had called into Forth.
    UnwoundThroughHost,
    /// A region (code, dictionary, heap) is full.
    OutOfSpace(&'static str),
    /// The host asked to stop the running code (`reva_vm::Machine::interrupt`).
    Interrupted,
    /// `(call)` of an address that is not a virtual-library function: the
    /// portable core never runs native code (see docs/portability.md).
    NativeCall { addr: u32 },
    /// An OS service the host does not allow, with what would enable it.
    NotPermitted {
        what: &'static str,
        hint: &'static str,
    },
    /// A host call this host cannot answer (a service it does not have).
    Unavailable(String),
}

/// Where unsupported code is explained.
pub const PORTABILITY_DOC: &str = "docs/portability.md";

/// What kind of x86 code `bytes` (an instruction, prefixes first) is, for
/// fault messages: names the family the portable core leaves out, so a
/// reader knows at once whether it is floating point, a vector extension,
/// a privileged instruction or a plain gap in the decoder.
pub fn insn_class(bytes: &[u8]) -> &'static str {
    let mut i = 0;
    let mut sse_prefix = false;
    while let Some(&b) = bytes.get(i) {
        match b {
            0x26 | 0x2e | 0x36 | 0x3e | 0x64 | 0x65 => return "segment override",
            0xf0 => return "lock prefix",
            0x66 | 0xf2 | 0xf3 => {
                sse_prefix = true;
                i += 1;
            }
            _ => break,
        }
    }
    let Some(&op) = bytes.get(i) else {
        return "x86";
    };
    match op {
        0xd8..=0xdf | 0x9b => "x87 floating point",
        0xe4..=0xe7 | 0xec..=0xef | 0x6c..=0x6f => "I/O port (privileged)",
        0xfa | 0xfb | 0xf4 | 0xcf => "privileged",
        0x8e | 0x8c | 0x06 | 0x07 | 0x0e | 0x16 | 0x17 | 0x1e | 0x1f => "segment register",
        0xcc..=0xce => "software interrupt",
        0x0f => match bytes.get(i + 1).copied().unwrap_or(0) {
            0x00 | 0x01 | 0x06 | 0x08 | 0x09 | 0x20..=0x23 | 0x30 | 0x32 | 0x33 => "privileged",
            0x0b => "undefined instruction (ud2)",
            0xa0 | 0xa1 | 0xa8 | 0xa9 => "segment register",
            0xa2 | 0x31 => "processor identification (cpuid/rdtsc)",
            0x10..=0x17 | 0x28..=0x2f | 0x50..=0x5f | 0xc2 | 0xc6 => "SSE",
            0x60..=0x7f | 0xd0..=0xff if sse_prefix => "SSE2",
            0x60..=0x7f | 0xd0..=0xff => "MMX",
            _ => "x86",
        },
        _ => "x86",
    }
}

impl fmt::Display for Fault {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Fault::BadAddress { addr, len } => {
                write!(f, "bad memory access: {len} byte(s) at {addr:#010x}")
            }
            Fault::BadOpcode { eip, bytes } => {
                let class = insn_class(bytes);
                write!(f, "unsupported {class} instruction at {eip:#010x}:")?;
                for b in bytes {
                    write!(f, " {b:02x}")?;
                }
                write!(f, " (see {PORTABILITY_DOC})")
            }
            Fault::DivideError { eip } => write!(f, "divide error at {eip:#010x}"),
            Fault::BadGate { addr } => write!(f, "no core routine at {addr:#010x}"),
            Fault::Trap { eip, what } => write!(f, "{what} at {eip:#010x}"),
            Fault::StackUnderflow => write!(f, "stack underflow"),
            Fault::ReturnStackOverflow => write!(f, "return stack overflow"),
            Fault::NotImplemented(w) => write!(f, "'{w}' is not implemented in this port yet"),
            Fault::InputInNestedCall => {
                write!(f, "input requested inside a host callback (not resumable)")
            }
            Fault::UnwoundThroughHost => write!(f, "throw unwound through a host callback"),
            Fault::OutOfSpace(what) => write!(f, "out of {what} space"),
            Fault::Interrupted => write!(f, "interrupted"),
            Fault::NativeCall { addr } => write!(
                f,
                "call to native code at {addr:#010x}: the portable core runs no native \
                 libraries (see {PORTABILITY_DOC})"
            ),
            Fault::Unavailable(why) => write!(f, "{why} (see {PORTABILITY_DOC})"),
            Fault::NotPermitted { what, hint } => {
                write!(
                    f,
                    "{what} is not allowed here: {hint} (see {PORTABILITY_DOC})"
                )
            }
        }
    }
}

impl std::error::Error for Fault {}

