    fn transcendentals() {
        // fldln2 fld1 fadd st0,st0 ... fyl2x: ln(2) * log2(2) = ln 2;  fsin of pi/2
        let (mut c, _) = run(
            &[0xd9, 0xe8, 0xd8, 0xc0, 0xd9, 0xed, 0xd9, 0xc9, 0xd9, 0xf1],
            &[],
        );
