/// a finite non-zero value by zero (ZE).
pub fn arith_value(op: FArith, d: f64, s: f64) -> (f64, bool) {
    let (num, den) = match op {
        FArith::Div => (d, s),
        FArith::Divr => (s, d),
        _ => (1.0, 1.0),
    };
    let zero_divide = den == 0.0 && num.is_finite() && num != 0.0;
    let r = match op {
        FArith::Add => d + s,
        FArith::Mul => d * s,
        FArith::Sub => d - s,
        FArith::Subr => s - d,
        FArith::Div | FArith::Divr => num / den,
    };
    (r, zero_divide)
