use reva_x86::{Exec, decode as new_decode};

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 { self.0 ^= self.0 << 13; self.0 ^= self.0 >> 7; self.0 ^= self.0 << 17; self.0 }
    fn byte(&mut self) -> u8 { self.next() as u8 }
}

// Opcode bytes Reva code uses, to bias the streams toward valid instructions.
const COMMON: &[u8] = &[0x01,0x03,0x29,0x2b,0x31,0x33,0x39,0x3b,0x09,0x21,0x11,0x19,0x85,0x89,0x8b,0x8d,0x83,0x81,0xc1,0xd1,0xd3,0xf7,0xf6,0xff,0xfe,0xad,0xab,0xa4,0xa5,0xaa,0xac,0xae,0xa6,0x40,0x48,0x50,0x58,0x99,0x98,0x66,0xf3,0xf2,0x0f,0x74,0x75,0x7c,0x7e,0xeb,0xe8,0xe9,0xc3,0xc2,0x90,0xb8,0xb0,0x93,0x87,0x86,0xc6,0xc7,0xd8,0xd9,0xda,0xdb,0xdc,0xdd,0xde,0xdf,0xe2,0xe3,0xa0,0xa1,0xa2,0xa3,0xf8,0xf9,0xf5,0xfc,0xfd,0x68,0x6a,0x69,0x6b,0x8f,0x91,0xc0,0xd0,0xd2,0xa8,0xa9,0x84,0x80,0x88,0x8a,0x0c,0x24,0x34,0x3c,0x05,0x2d];

fn fill(r: &mut Rng, buf: &mut [u8]) {
    for b in buf.iter_mut() {
        *b = if r.next() % 3 == 0 { r.byte() } else { COMMON[(r.next() % COMMON.len() as u64) as usize] };
    }
}

fn main() {
    let mut r = Rng(0x9e3779b97f4a7c15);
    let n: usize = std::env::args().nth(1).and_then(|s| s.parse().ok()).unwrap_or(200_000);
    // decoder: every single opcode byte with random tails, then random streams
    let mut decodes = 0;
    for i in 0..n {
        let mut code = [0u8; 16];
        fill(&mut r, &mut code);
        if i < 65536 { code[0] = i as u8; code[1] = (i >> 8) as u8; }
        let mut om = old_x86::mem::Memory::new(0x3000);
        let mut nm = reva_x86::mem::Memory::new(0x3000);
        om.write_bytes(0x2ff0, &code).unwrap();
        nm.write_bytes(0x2ff0, &code).unwrap();
        for at in [0x2ff0u32, 0x2ff8, 0x2ffc] {
            let a = format!("{:?}", old_x86::decode(&om, at));
            let b = format!("{:?}", new_decode(&nm, at));
            assert_eq!(a, b, "decode {:02x?} at {at:#x}", code);
            decodes += 1;
        }
