    // executor: random programs on random state, step by step
    let mut steps = 0;
    for _ in 0..n / 4 {
        let mut code = [0u8; 96];
        fill(&mut r, &mut code);
        let mut om = old_x86::mem::Memory::new(0x10000);
        let mut nm = reva_x86::mem::Memory::new(0x10000);
        let mut data = vec![0u8; 0x2000];
        for b in data.iter_mut() { *b = r.byte(); }
        for (o, n) in [(&mut om, ()), ].into_iter().map(|x| (x.0, x.1)) { let _ = (o, n); }
        om.write_bytes(0x4000, &data).unwrap(); nm.write_bytes(0x4000, &data).unwrap();
        om.write_bytes(0x2000, &code).unwrap(); nm.write_bytes(0x2000, &code).unwrap();
        let mut oc = old_x86::Cpu { esp_floor: 0x8000, ..Default::default() };
        let mut nc = reva_x86::Cpu { esp_floor: 0x8000, ..Default::default() };
        for i in 0..8 {
            let v = match r.next() % 4 { 0 => 0x4000 + (r.next() % 0x1f00) as u32, 1 => (r.next() % 16) as u32, _ => r.next() as u32 };
            oc.r[i] = v; nc.r[i] = v;
        }
        oc.r[4] = 0x9000; nc.r[4] = 0x9000; // ESP
        let fl = r.next();
        (oc.cf, oc.zf, oc.sf, oc.of, oc.pf, oc.df) = (fl & 1 != 0, fl & 2 != 0, fl & 4 != 0, fl & 8 != 0, fl & 16 != 0, fl & 32 != 0);
        (nc.cf, nc.zf, nc.sf, nc.of, nc.pf, nc.df) = (oc.cf, oc.zf, oc.sf, oc.of, oc.pf, oc.df);
        if fl & 64 != 0 { oc.r[1] &= 0xff; nc.r[1] &= 0xff; } // keep rep counts small sometimes
        oc.r[1] &= 0xfff; nc.r[1] &= 0xfff;
        oc.eip = 0x2000; nc.eip = 0x2000;
        for _ in 0..64 {
            if oc.eip < 0x2000 || oc.eip >= 0x2000 + code.len() as u32 { break; }
            let oi = old_x86::decode(&om, oc.eip);
            let ni = new_decode(&nm, nc.eip);
            assert_eq!(format!("{oi:?}"), format!("{ni:?}"));
            let (Ok(oi), Ok(ni)) = (oi, ni) else { break };
            let a = oc.exec(&mut om, &oi);
            let b = nc.exec(&mut nm, &ni);
            assert_eq!(format!("{a:?}"), format!("{b:?}"), "exec {oi:?}");
            assert_eq!(format!("{oc:?}"), format!("{nc:?}"), "state after {oi:?}");
            assert_eq!(om.as_bytes(), nm.as_bytes(), "memory after {oi:?}");
            steps += 1;
            if a.is_err() { break; }
        }
    }
    println!("equal: {decodes} decodes, {steps} executed steps");
}
