647	    pub fn describe_addr(&self, addr: u32) -> String {
648	        if let Some(g) = Gate::from_addr(addr) {
649	            return format!("core:{}", g.name());
650	        }
651	        let mut best: Option<(u32, u32)> = None;
652	        let mut e = self.mem.read_u32(self.var(st::LAST)).unwrap_or(0);
653	        let mut guard = 0;
