803	    /// Report a fault and return to the interactive loop, cleaning up the
804	    /// way `interpret`'s failure path does.
805	    fn recover(&mut self, host: &mut dyn Host, f: Fault) {
806	        let eip = self.cpu.eip;
807	        let at = self.describe_addr(eip);
808	        host.write(format!("\n*** {f} (in {at}, eip {eip:#010x})\n").as_bytes());
809	        let _ = self.rollback_definition();
810	        for (a, v) in [
811	            (st::IS_COMPILING, 0),
812	            (st::DIDHEADER, 0),
813	            (st::SOURCE, 0),
814	            (st::HANDLER, 0),
815	            (st::RP0_SAVED, RP0),
816	        ] {
817	            let _ = self.mem.write_u32(a, v);
818	        }
819	        let tp = self.var(st::TP);
820	        let _ = self.mem.write_u32(st::TIN, tp);
821	        self.cpu.r[ESI as usize] = S0;
822	        self.cpu.r[EAX as usize] = 0;
823	        self.cpu.r[ESP as usize] = RP0;
824	        self.cpu.df = false;
