839	    /// Undo a half-compiled definition (`interpret`'s `.fail` path).
840	    pub fn rollback_definition(&mut self) -> Result<(), Fault> {
841	        if self.var(st::IS_COMPILING) != 0 && self.var(st::DIDHEADER) != 0 {
842	            let lasth = self.var(st::LASTH);
843	            let lastd = self.var(st::LASTD);
844	            let lastl = self.var(st::LASTL);
845	            let lastp = self.var(st::LAST);
846	            self.mem.write_u32(st::H, lasth)?;
847	            self.mem.write_u32(st::D, lastd)?;
848	            self.mem.write_u32(lastp, lastl)?;
849	        }
850	        self.mem.write_u32(st::IS_COMPILING, 0)?;
851	        self.mem.write_u32(st::DIDHEADER, 0)
852	    }
