        s,
        "<path fill=\\"none\\" stroke=\\"#{:06x}\\" stroke-width=\\"{}\\" \\
         stroke-linecap=\\"round\\" stroke-linejoin=\\"round\\" d=\\"M{} {}",
        first.rgb,
        num(first.width),
        num(first.x1),
        num(-first.y1)
    );
    let mut j = i;
    loop {
        let g = segs[j];
        let _ = write!(s, " L{} {}", num(g.x2), num(-g.y2));
        j += 1;
        let joined = segs.get(j).is_some_and(|n| {
            n.x1 == g.x2 && n.y1 == g.y2 && n.rgb == g.rgb && n.width == g.width
        });
        if !joined {
            break;
        }
    }
    s.push_str("\\"/>\\n");
    j
}

