/// What a host lends the VM.
pub trait Resources {
    /// Sources the host serves for `include` and `slurp` *before* the file
    /// system ([`Resources::fs`]): the embedded boot source, normally
    /// (reva-embedded's `file`).  `None` means "ask the file system".
